55	
56	    @Autowired
57	    private ObjectMapper objectMapper;
58	
59	    // ---------- 主流程：创建、命中、结束时刻、取消释放 ----------
60	
61	    @Test
62	    void createHitEndBoundaryCancelAndRelease() throws Exception {
63	        Ctx ctx = newContext();
64	        publishProgram(ctx, "ov-seg", T_10, T_11);
65	
66	        // 创建即 ACTIVE；区间 10:20-10:40
67	        createOverride(ctx, "req-create", "ov-1", ctx.newsAsset, ctx.newsGrant, 5, T_1020, T_1040)
68	                .andExpect(status().isOk())
69	                .andExpect(jsonPath("$.overrideKey").value(ctx.key("ov-1")))
70	                .andExpect(jsonPath("$.status").value("ACTIVE"))
71	                .andExpect(jsonPath("$.priority").value(5))
72	                .andExpect(jsonPath("$.grantId").value(ctx.newsGrant))
73	                .andExpect(jsonPath("$.cancelRequestId").isEmpty())
74	                .andExpect(jsonPath("$.cancelledAt").isEmpty());
75	
76	        // 区间外仍是原节目
77	        playout(ctx, "2026-09-22T10:10:00.000+08:00")
78	                .andExpect(jsonPath("$.source").value("PROGRAM"))
79	                .andExpect(jsonPath("$.assetId").value(ctx.movieAsset));
80	        // 区间内：EMERGENCY 优先于已发布节目，返回素材与 overrideKey
81	        playout(ctx, T_1020)
82	                .andExpect(jsonPath("$.source").value("EMERGENCY"))
83	                .andExpect(jsonPath("$.assetId").value(ctx.newsAsset))
84	                .andExpect(jsonPath("$.overrideKey").value(ctx.key("ov-1")))
85	                .andExpect(jsonPath("$.publicationId").isEmpty())
86	                .andExpect(jsonPath("$.reason").isEmpty());
87	        playout(ctx, T_1030)
88	                .andExpect(jsonPath("$.source").value("EMERGENCY"));
89	        // 结束时刻不再命中（左闭右开）
90	        playout(ctx, T_1040)
91	                .andExpect(jsonPath("$.source").value("PROGRAM"));
92	
93	        // 取消
94	        postJson("/api/emergency-overrides/" + ctx.key("ov-1") + "/cancel",
95	                        Map.of("requestId", "req-cancel"))
96	                .andExpect(status().isOk())
97	                .andExpect(jsonPath("$.status").value("CANCELLED"))
98	                .andExpect(jsonPath("$.cancelRequestId").value("req-cancel"))
99	                .andExpect(jsonPath("$.cancelledAt").isNotEmpty());
100	
101	        // 明细保留取消情况与原授权关联
102	        getOverride(ctx, "ov-1")
103	                .andExpect(status().isOk())
104	                .andExpect(jsonPath("$.status").value("CANCELLED"))
105	                .andExpect(jsonPath("$.grantId").value(ctx.newsGrant))
106	                .andExpect(jsonPath("$.cancelRequestId").value("req-cancel"));
107	
108	        // 取消后播出回到节目
109	        playout(ctx, T_1030)
110	                .andExpect(jsonPath("$.source").value("PROGRAM"))
111	                .andExpect(jsonPath("$.assetId").value(ctx.movieAsset));
112	
113	        // 取消提交后释放该冲突范围：同频道同优先级与已取消区间重叠可再创建
114	        createOverride(ctx, "req-create-2", "ov-2", ctx.newsAsset, ctx.newsGrant, 5,
115	                        "2026-09-22T10:25:00.000+08:00", "2026-09-22T10:35:00.000+08:00")
