120	    // ---------- 区间规则：相邻合法、跨优先级允许重叠、时长与同日校验 ----------
121	
122	    @Test
123	    void adjacentSamePriorityAndDifferentPriorityOverlapAllowed() throws Exception {
124	        Ctx ctx = newContext();
