154	        createOverride(ctx, "bad-3", "k3", ctx.newsAsset, ctx.newsGrant, 5,
155	                        "2026-09-22T23:50:00.000+08:00", "2026-09-23T00:10:00.000+08:00")
156	                .andExpect(status().isBadRequest());
157	        // 400：优先级越界（Bean Validation）
158	        mvc.perform(post("/api/emergency-overrides").contentType(MediaType.APPLICATION_JSON)
159	                        .content(objectMapper.writeValueAsString(overrideBody(
160	                                "bad-4", ctx.key("k4"), ctx.channel, ctx.newsAsset,
161	                                ctx.newsGrant, 10, T_1020, T_1030))))
162	                .andExpect(status().isBadRequest());
163	        // 400：缺少 requestId
164	        mvc.perform(post("/api/emergency-overrides").contentType(MediaType.APPLICATION_JSON)
165	                        .content(objectMapper.writeValueAsString(overrideBody(
166	                                null, ctx.key("k5"), ctx.channel, ctx.newsAsset,
167	                                ctx.newsGrant, 5, T_1020, T_1030))))
168	                .andExpect(status().isBadRequest());
