172	    }
173	
174	    // ---------- 404 / 409 / 422 分支 ----------
175	
176	    @Test
177	    void notFoundConflictAndUnprocessableBranches() throws Exception {
178	        Ctx ctx = newContext();
179	
180	        // 404：频道/素材/授权/明细不存在
181	        createOverride(ctx, "nf-1", "nf1", ctx.newsAsset, ctx.newsGrant, 5, T_1020, T_1030)
182	                .andExpect(status().isOk());
183	        mvc.perform(post("/api/emergency-overrides").contentType(MediaType.APPLICATION_JSON)
184	                        .content(objectMapper.writeValueAsString(overrideBody(
