422	
423	    @Test
424	    void concurrentCreateAndRevokeFollowsCommitOrder() throws Exception {
425	        Ctx ctx = newContext();
426	        publishProgram(ctx, "prog", T_10, T_11);
427	
428	        CountDownLatch ready = new CountDownLatch(2);
429	        CountDownLatch start = new CountDownLatch(1);
430	        ExecutorService pool = Executors.newFixedThreadPool(2);
431	        try {
432	            Future<Integer> createFuture = pool.submit(() -> {
433	                ready.countDown();
434	                start.await(5, TimeUnit.SECONDS);
435	                return mvc.perform(post("/api/emergency-overrides")
436	                                .contentType(MediaType.APPLICATION_JSON)
437	                                .content(objectMapper.writeValueAsString(overrideBody(
438	                                        "race-req", ctx.key("race"), ctx.channel,
439	                                        ctx.newsAsset, ctx.newsGrant, 5, T_1020, T_1040))))
440	                        .andReturn().getResponse().getStatus();
441	            });
442	            Future<Integer> revokeFuture = pool.submit(() -> {
443	                ready.countDown();
444	                start.await(5, TimeUnit.SECONDS);
445	                return mvc.perform(post("/api/grants/" + ctx.newsGrant + "/revoke")
446	                                .contentType(MediaType.APPLICATION_JSON)
447	                                .content(objectMapper.writeValueAsString(Map.of("requestId", "race-rv"))))
448	                        .andReturn().getResponse().getStatus();
449	            });
450	            ready.await(5, TimeUnit.SECONDS);
451	            start.countDown();
452	            int createStatus = createFuture.get(30, TimeUnit.SECONDS);
453	            int revokeStatus = revokeFuture.get(30, TimeUnit.SECONDS);
454	
455	            // 撤销本身成功；创建要么 422（撤销先提交），要么 200（创建先提交）
456	            assertThat(revokeStatus).isEqualTo(200);
457	            assertThat(createStatus).isIn(200, 422);
458	
459	            MvcResult detail = getOverride(ctx, "race").andReturn();
460	            if (createStatus == 422) {
461	                // 撤销先提交：插播不存在
462	                assertThat(detail.getResponse().getStatus()).isEqualTo(404);
463	            } else {
464	                // 创建先提交：插播保留 ACTIVE 与原授权关联，但后续播出必须排除该插播
465	                JsonNode json = readJson(detail);
466	                assertThat(detail.getResponse().getStatus()).isEqualTo(200);
467	                assertThat(json.get("status").asText()).isEqualTo("ACTIVE");
468	                assertThat(json.get("grantId").asLong()).isEqualTo(ctx.newsGrant);
469	            }
470	            // 无论提交顺序如何，授权已撤销，10:30 都不能命中 EMERGENCY
471	            playout(ctx, T_1030)
472	                    .andExpect(jsonPath("$.source").value("PROGRAM"))
473	                    .andExpect(jsonPath("$.assetId").value(ctx.movieAsset));
474	        } finally {
475	            pool.shutdownNow();
476	        }
477	    }
