604	    private interface ThrowingSupplier {
605	        Integer get(int index) throws Exception;
606	    }
607	
608	    private List<Integer> runConcurrently(int threads, ThrowingSupplier action) throws Exception {
609	        ExecutorService pool = Executors.newFixedThreadPool(threads);
610	        CountDownLatch ready = new CountDownLatch(threads);
611	        CountDownLatch start = new CountDownLatch(1);
612	        List<Future<Integer>> futures = new ArrayList<>();
613	        for (int i = 0; i < threads; i++) {
614	            final int index = i;
615	            futures.add(pool.submit(() -> {
616	                ready.countDown();
617	                start.await(5, TimeUnit.SECONDS);
618	                return action.get(index);
619	            }));
620	        }
