                .andExpect(jsonPath("$.error").value("PLAY_KEY_CONFLICT"));
        // 相同 playKey 改频道：409
        Ctx other = newContext();
        postJson("/api/playout-decisions",
                        registerBody("req-idem-4", ctx.key("pk-i"), other.channel, T_1030))
